import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import org.admany.noplayernametags.commands.NpntCommand;
import org.admany.noplayernametags.config.ConfigManager;
import org.admany.noplayernametags.network.NetworkHandler;
import org.admany.noplayernametags.server.ServerState;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

@Mod(value="noplayernametags")
public class NoPlayerNameTagsMod {
    public static final String MODID = "noplayernametags";
    public static final Logger LOGGER = LogManager.getLogger();

    public NoPlayerNameTagsMod() {
        MinecraftForge.EVENT_BUS.register((Object)this);
        ConfigManager.initializeGlobals();
        NetworkHandler.register();
    }

    @SubscribeEvent
    public void onServerStarting(ServerStartingEvent event) {
        ServerState.load(event.getServer());
    }

    @SubscribeEvent
    public void onServerStopping(ServerStoppingEvent event) {
        ServerState.save(event.getServer());
    }

    @SubscribeEvent
    public void onRegisterCommands(RegisterCommandsEvent event) {
        NpntCommand.register((CommandDispatcher<CommandSourceStack>)event.getDispatcher());
    }

    @SubscribeEvent
    public void onPlayerLoggedIn(PlayerEvent.PlayerLoggedInEvent event) {
        Player player = event.getEntity();
        if (player instanceof ServerPlayer) {
            ServerPlayer player2 = (ServerPlayer)player;
            NetworkHandler.sendSettingsTo(player2, ServerState.getMode(), ServerState.getDistanceLimit(), ServerState.getOverrides());
        }
    }
}

