public final class ServerState {
    private static volatile NameTagMode currentMode = NameTagMode.VISUAL;
    private static volatile int distanceLimit = 0;
    private static final ConcurrentHashMap<UUID, NameTagMode> overrides = new ConcurrentHashMap();

    private ServerState() {
    }

    public static void load(MinecraftServer server) {
        WorldDataManager.WorldData data = WorldDataManager.loadOrCreate(server);
        currentMode = NameTagMode.fromId(data.mode);
        if (currentMode == null) {
            currentMode = NameTagMode.fromId(ConfigManager.DEFAULT_MODE);
        }
        distanceLimit = Math.max(0, data.distanceLimit);
        overrides.clear();
        if (data.overrides != null) {
            for (Map.Entry<String, String> entry : data.overrides.entrySet()) {
                try {
                    UUID id = UUID.fromString(entry.getKey());
                    overrides.put(id, NameTagMode.fromId(entry.getValue()));
                }
                catch (Exception exception) {}
            }
        }
    }

    public static void save(MinecraftServer server) {
        NameTagMode mode = currentMode != null ? currentMode : NameTagMode.fromId(ConfigManager.DEFAULT_MODE);
        WorldDataManager.WorldData data = new WorldDataManager.WorldData();
        data.mode = mode.id();
        data.distanceLimit = distanceLimit;
        data.overrides = new HashMap<String, String>();
        overrides.forEach((id, overrideMode) -> data.overrides.put(id.toString(), overrideMode.id()));
        WorldDataManager.save(server, data);
    }

    public static NameTagMode getMode() {
        return currentMode;
    }

    public static int getDistanceLimit() {
        return distanceLimit;
    }

